    const demi = Math.max(200, W / 2);
    const p = Math.max(-1, Math.min(1, (sx - demi) / demi)) * 0.75;
    const d = Math.hypot(sx - demi, sy - Math.max(150, H / 2));
    return { p: p, a: 1 / (1 + Math.pow(d / (demi * 1.4), 2)) };
